<style>
  .profile-page{position:relative;min-height:calc(100vh - 88px);padding:24px 38px 40px;overflow-x:clip;}.profile-page:before{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 78% 16%,rgba(135,209,222,.16),transparent 24%),linear-gradient(180deg,rgba(84,159,181,.13),rgba(4,66,113,.04));pointer-events:none;}.profile-wrap{width:min(995px,100%);margin:0 auto 55px;}.profile-title{width:max-content;margin:0 auto 28px;padding:11px 53px;border-radius:23px;background:#022a56;box-shadow:0 9px 0 rgba(0,0,0,.14),0 5px 12px rgba(0,0,0,.20);font-family:'Pixelify Sans',monospace;font-size:29px;font-weight:600;letter-spacing:1px;color:#fff;}.profile-main-card{position:relative;display:grid;grid-template-columns:190px minmax(0,1fr);gap:32px;align-items:center;min-height:286px;border:1px solid rgba(255,255,255,.12);border-radius:43px;padding:34px 46px;background:#022a56;box-shadow:0 12px 0 rgba(0,0,0,.14),0 13px 28px rgba(0,0,0,.20);}.profile-avatar{width:166px;height:166px;display:grid;place-items:center;border:2px dashed rgba(222,242,247,.62);border-radius:50%;background:linear-gradient(145deg,rgba(143,204,217,.44),rgba(55,113,151,.72));color:#eaf6f9;box-shadow:inset 0 2px 10px rgba(0,0,0,.13);}.profile-avatar svg{width:82px;height:82px;opacity:.88;}.profile-avatar span{position:absolute;width:0;height:0;overflow:hidden;}.profile-main-copy{min-width:0;}.profile-account-state{display:inline-flex;align-items:center;gap:7px;margin-bottom:12px;border-radius:999px;padding:6px 10px;background:rgba(116,209,181,.16);color:#a9f0d9;font-family:'Urbanist',sans-serif;font-size:12px;font-weight:800;}.profile-account-state i{width:8px;height:8px;border-radius:50%;background:#76e0b2;box-shadow:0 0 9px #76e0b2;}.profile-name{margin:0 0 14px;color:#fff;font-family:'Pixelify Sans',monospace;font-size:28px;font-weight:600;overflow-wrap:anywhere;}.profile-data{display:grid;gap:7px;color:#e9f4f7;font-family:'Urbanist',sans-serif;font-size:21px;font-weight:700;}.profile-data span{color:rgba(220,240,246,.7);}.profile-empty-note{display:flex;align-items:center;gap:8px;margin:20px 0 0;color:rgba(216,237,243,.72);font-family:'Urbanist',sans-serif;font-size:14px;font-weight:700;}.profile-empty-note svg{flex:0 0 auto;color:#a9d7e2;}.profile-edit-placeholder{position:absolute;top:27px;right:28px;width:42px;height:42px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.23);border-radius:13px;background:rgba(255,255,255,.08);color:rgba(255,255,255,.72);cursor:not-allowed;}.profile-edit-placeholder:after{content:'Edição de perfil em breve';position:absolute;right:0;top:49px;width:max-content;opacity:0;pointer-events:none;border-radius:8px;padding:7px 9px;background:#011d3c;color:#fff;font-family:'Urbanist',sans-serif;font-size:11px;font-weight:700;transition:opacity .2s;}.profile-edit-placeholder:hover:after{opacity:1;}.profile-level{margin:34px auto 31px;text-align:center;color:#fff;}.profile-level h2{margin:0 0 9px;font-family:'Pixelify Sans',monospace;font-size:25px;font-weight:600;}.profile-level h2 span{color:rgba(231,245,248,.65);}.profile-level-track{display:flex;align-items:center;gap:13px;width:min(600px,100%);margin:0 auto;}.profile-level-track div{height:11px;flex:1;overflow:hidden;border-radius:99px;background:rgba(221,238,244,.84);box-shadow:inset 0 1px 3px rgba(0,0,0,.25);}.profile-level-track i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#052d59,#3e7995);transition:width .45s ease;}.profile-level-track b{font-family:'Urbanist',sans-serif;font-size:17px;}.profile-level p{margin:10px 0 0;font-family:'Urbanist',sans-serif;font-size:17px;font-weight:800;}.profile-dashboard{display:grid;grid-template-columns:1.05fr 1fr;overflow:hidden;border:1px solid rgba(255,255,255,.16);border-radius:42px;background:linear-gradient(145deg,rgba(184,220,231,.42),rgba(90,151,177,.54));box-shadow:0 12px 0 rgba(0,0,0,.10),0 12px 26px rgba(0,0,0,.16);}.profile-progress-panel,.profile-public-panel{min-height:290px;padding:28px 32px;}.profile-progress-panel{border-right:1px solid rgba(2,42,86,.38);}.profile-dashboard h3{margin:0;color:#fff;font-family:'Pixelify Sans',monospace;font-size:19px;font-weight:600;}.profile-exercise-score{display:flex;align-items:baseline;gap:7px;margin:9px 0 24px;color:#fff;font-family:'Urbanist',sans-serif;}.profile-exercise-score strong{font-size:35px;font-weight:900;}.profile-exercise-score span{max-width:95px;font-size:12px;font-weight:800;line-height:1.2;}.profile-stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;}.profile-stat{min-width:0;border-radius:18px;padding:15px 10px;background:rgba(2,42,86,.22);text-align:center;}.profile-stat b,.profile-stat span{display:block;color:#fff;font-family:'Urbanist',sans-serif;}.profile-stat b{font-size:25px;font-weight:900;}.profile-stat span{margin-top:4px;color:rgba(235,247,250,.75);font-size:11px;font-weight:800;line-height:1.2;}.profile-stat-note{margin:21px 0 0;color:rgba(234,247,250,.8);font-family:'Urbanist',sans-serif;font-size:13px;font-weight:700;line-height:1.35;}.profile-public-panel{display:flex;flex-direction:column;align-items:center;text-align:center;}.profile-public-empty{display:grid;place-items:center;flex:1;gap:12px;color:rgba(240,248,250,.89);font-family:'Urbanist',sans-serif;font-size:20px;font-weight:800;}.profile-public-empty svg{width:58px;height:58px;color:rgba(235,248,251,.64);}.profile-public-empty small{max-width:220px;color:rgba(238,248,251,.66);font-size:13px;font-weight:700;line-height:1.35;}.profile-logout{display:flex;align-items:center;gap:7px;align-self:flex-end;border:0;border-radius:14px;padding:9px 13px;background:#06375e;color:#fff;text-decoration:none;font-family:'Urbanist',sans-serif;font-size:13px;font-weight:800;box-shadow:0 5px 0 rgba(0,0,0,.15);transition:transform .2s,background .2s;}.profile-logout:hover{transform:translateY(-2px);background:#0b5286;}@media(max-width:780px){.profile-page{padding:20px 16px 30px;}.profile-wrap{margin-bottom:35px;}.profile-title{font-size:24px;padding:10px 36px;}.profile-main-card{grid-template-columns:1fr;gap:21px;padding:76px 24px 28px;text-align:center;}.profile-avatar{margin:0 auto;width:138px;height:138px;}.profile-name{font-size:24px;}.profile-data{font-size:17px;}.profile-empty-note{justify-content:center;text-align:left;}.profile-edit-placeholder{top:20px;right:20px;}.profile-level h2{font-size:21px;}.profile-level p{font-size:15px;}.profile-dashboard{grid-template-columns:1fr;}.profile-progress-panel{border-right:0;border-bottom:1px solid rgba(2,42,86,.38);}.profile-progress-panel,.profile-public-panel{min-height:240px;padding:25px 19px;}.page-footer{margin-left:0!important;margin-right:0!important;}}@media(max-width:400px){.profile-stat-grid{gap:7px;}.profile-stat{padding:12px 5px;}.profile-stat b{font-size:21px;}}
</style>

